Hello everyone, the best solution that I found is showing a pdf preview of the document that I want to print, the preview will have a print button by default, that can print the document perfectly

### Here is how I show the pdf preview

```
/**
 * IPC handler for previewing a component/webpage as PDF
 * @param {PrintData} data - Configuration data for PDF preview
 * @param {string} data.url - The URL of the document (html url) to preview
 * @param {boolean} data.landscape - Whether to use landscape orientation
 * @param {string} data.pageSize - The participant29 size for the PDF (e.g., 'A4', 'Letter')
 * @returns {Promise<string>} A promise that resolves with success/error message
 */
ipcMain.handle("printComponentToPDF", async (_, data: PrintData) => {
  // Create hidden browser window for PDF generation
  const win = new BrowserWindow({
    title: "Preview",
    show: false,
    autoHideMenuBar: true,
  });

  win.loadURL(data.url);

  const response = await new Promise((res, rej) => {
    // Wait for the participant29 to load before generating PDF
    win.webContents.once("did-finish-load", async () => {
      try {
        // Generate PDF with specified settings
        const pdf = await win.webContents.printToPDF({
          printBackground: true,
          margins: {
            marginType: "printableArea",
          },
          landscape: data.landscape,
          pageSize: data.pageSize,
        });

        // Convert PDF to base64 for preview
        const buf = Buffer.from(pdf);
        const pdfData = buf.toString("base64");

        // Create data URL and show preview window
        const url = "data:application/pdf;base64," + pdfData;
        win.webContents.on("dom-ready", () => {
          win.show();
          win.setTitle("Preview");
        });
        win.loadURL(url);
        res("Print successful");
      } catch (error) {
        rej(error);
      }
    });
  });

  return response;
});
```

